 @Test void all37ActualCompressedSourcesHaveIndependentIncludeReaderAndProductPins()throws Exception{
  var a=TestCdR31aAssets.actual().assets();var l=a.loadMetadata();assertTrue(l.ownsAssets(a));assertFalse(l.ownsAssets(null));assertSame(a.identity(),l.identity());assertEquals(37,CdR31aLoadMetadata.SourceId.values().length);var lines=SOURCES.strip().lines().toList();for(int i=0;i<lines.size();i++){var p=lines.get(i).split(" ");var id=CdR31aLoadMetadata.SourceId.valueOf(p[0]);var s=l.source(id);assertEquals(i,id.ordinal());assertEquals(Integer.parseInt(p[1],16),s.fileOffset());assertEquals(Integer.parseInt(p[2]),s.includeBytes());assertEquals(Integer.parseInt(p[3]),s.javaReaderBytes());assertEquals(Integer.parseInt(p[4]),s.expectedJavaConsumedBytes());assertEquals(Integer.parseInt(p[5]),s.outputBytes());assertEquals(p[6],TestCdR31aAssets.hash(l.canonicalView(id).copy()));assertEquals(p[7],TestCdR31aAssets.hash(l.javaView(id).copy()));var d=l.decoded(id);assertSame(d,l.decoded(id));assertEquals(s.expectedJavaConsumedBytes(),d.consumedInputBytes());assertEquals(s.outputBytes(),d.bytes().length());assertEquals(p[8],TestCdR31aAssets.hash(d.bytes().copy()));assertThrows(IndexOutOfBoundsException.class,()->l.javaView(id).unsignedByte(s.javaReaderBytes()));}
 }
 @Test void plc19IdsAllAliasesAndEveryNativeRowStayInSourceOrder()throws Exception{
  var a=TestCdR31aAssets.actual().assets();var l=a.loadMetadata();var raw=a.view(CdR31aAssets.Asset.PLC_LISTS);assertEquals(19,l.plcs().size());var bodies=new HashSet<Integer>();var encountered=new LinkedHashSet<CdR31aLoadMetadata.SourceId>();for(int id=0;id<19;id++){var p=l.plcs().get(id);int at=(short)raw.unsignedWord(2*id);assertEquals(id,p.nativeId());assertEquals(0xFAD0+at,p.bodyFileOffset());assertEquals(raw.unsignedWord(at)+1,p.entries().size());bodies.add(at);for(int j=0;j<p.entries().size();j++){var e=p.entries().get(j);var s=l.source(e.source());assertEquals(raw.unsignedLong(at+2+j*6),s.nativeAddress());assertEquals(raw.unsignedWord(at+6+j*6),e.vramAddress());assertTrue(s.outputBytes()<=0x10000-e.vramAddress());encountered.add(e.source());}}
  assertEquals(14,bodies.size());assertEquals(Arrays.asList(CdR31aLoadMetadata.SourceId.values()),List.copyOf(encountered));assertEquals(l.plcs().get(0).bodyFileOffset(),l.plcs().get(3).bodyFileOffset());for(int id:new int[]{13,14,15,17})assertEquals(l.plcs().get(2).bodyFileOffset(),l.plcs().get(id).bodyFileOffset());assertEquals(List.of(3,1),l.immediatePlcIds());assertEquals(2,l.conditionalQueuedPlcId());
 }
 @Test void realNeighborLookaheadAndUnreadTailsAreNeverSyntheticPadding()throws Exception{
  var l=TestCdR31aAssets.actual().assets().loadMetadata();int extra=0,tail=0;for(var id:CdR31aLoadMetadata.SourceId.values()){var s=l.source(id);assertTrue(s.javaReaderBytes()>=s.includeBytes());assertArrayEquals(l.canonicalView(id).copy(),l.javaView(id).slice(0,s.includeBytes()).copy());if(s.expectedJavaConsumedBytes()>s.includeBytes()){extra++;assertThrows(IOException.class,()->CdNemesisAsset.decode(l.canonicalView(id).copy(),s.outputBytes(),65536));}if(s.expectedJavaConsumedBytes()<s.includeBytes())tail++;}assertEquals(7,extra);assertTrue(tail>0);
 }
 @Test void levelProductIsTheSameRetainedSemanticDecodeAndUnownedValuesStayAbsent()throws Exception{
  var a=TestCdR31aAssets.actual().assets();var l=a.loadMetadata();assertSame(a.levelTilesDecode(),l.decoded(CdR31aLoadMetadata.SourceId.STAGE_GFX));assertEquals(0x82B6,l.source(CdR31aLoadMetadata.SourceId.STAGE_GFX).headerWord());assertFalse(Arrays.stream(CdR31aLoadMetadata.class.getDeclaredMethods()).anyMatch(x->List.of("service","current","submit","ready").contains(x.getName())));assertThrows(IllegalArgumentException.class,()->l.source(0x200000L));assertThrows(NullPointerException.class,()->CdR31aLoadMetadata.fromAssets(null));
 }
 @Test void actualPalettesCyclesSectionThresholdsAndPlanePointersAreCompleteMetadata()throws Exception{
  var l=TestCdR31aAssets.actual().assets().loadMetadata();assertEquals(6,l.palettes().size());int[] destinations={0xFB00,0xFB00,0xFB00,0xFB00,0xFB20,0xFB20};int[] counts={31,31,31,7,23,23};for(int i=0;i<6;i++){var p=l.palettes().get(i);assertEquals(i,p.nativeId());assertEquals(destinations[i],p.destinationWord());assertEquals(counts[i],p.longwordCounter());assertEquals((counts[i]+1)*4,p.bytes().length());}assertSame(l.palettes().get(0).bytes(),l.palettes().get(1).bytes());assertEquals(4,l.cycles().size());int[] scripts={8,34,32,6},colors={6,4,6,4};for(int i=0;i<4;i++){assertEquals(scripts[i],l.cycles().get(i).script().length());assertEquals(colors[i],l.cycles().get(i).colors().length());}assertEquals(List.of(new CdR11bLoadPlan.SectionArt(0x4A0,2,7),new CdR11bLoadPlan.SectionArt(0x1000,4,8),new CdR11bLoadPlan.SectionArt(0x1800,5,9),new CdR11bLoadPlan.SectionArt(0xFFFF,6,10)),l.sections());assertEquals(List.of(0xFFF708,0xFFF708,0xFFF710,0xFFF718),l.backgroundPointers());
 }
 @Test void sourceContainersAndPaletteMetadataNeverBecomeMutableOrAnArbitraryReader()throws Exception{
  var l=TestCdR31aAssets.actual().assets().loadMetadata();assertThrows(UnsupportedOperationException.class,()->l.sources().clear());assertThrows(UnsupportedOperationException.class,()->l.plcs().clear());assertThrows(UnsupportedOperationException.class,()->l.plcs().getFirst().entries().clear());assertThrows(UnsupportedOperationException.class,()->l.cycles().clear());assertThrows(IllegalArgumentException.class,()->new CdR31aLoadMetadata.PlcList(0,0xFCE6,l.plcs().getFirst().entries()));assertThrows(UnsupportedOperationException.class,()->l.sections().clear());assertThrows(java.nio.ReadOnlyBufferException.class,()->l.javaView(CdR31aLoadMetadata.SourceId.STAGE_GFX).buffer().put(0,(byte)1));for(var c:CdR31aLoadMetadata.class.getDeclaredConstructors())assertTrue(java.lang.reflect.Modifier.isPrivate(c.getModifiers()));
 }
 @Test void sameOwnerBorrowIsExactAndEqualDescriptorValuesAreNotAnOwnerFactory()throws Exception{
  var a=TestCdR31aAssets.actual().assets();var l=CdR31aLoadMetadata.fromAssets(a);assertNotSame(l,a.loadMetadata());assertTrue(l.ownsAssets(a));assertSame(a.identity(),l.identity());assertEquals(a.loadMetadata().sources(),l.sources());var f=TestCdR31aAssets.actual();var other=CdR31aAssets.fromPrograms(TestCdR31aAssets.source(f,f.image()),com.openggf.game.soniccd.CdStagePayload.R31A.stage());assertNotSame(a,other);assertEquals(a.identity(),other.identity());assertFalse(l.ownsAssets(other));assertTrue(Arrays.stream(CdR31aLoadMetadata.class.getDeclaredMethods()).filter(x->java.lang.reflect.Modifier.isPublic(x.getModifiers())&&java.lang.reflect.Modifier.isStatic(x.getModifiers())).allMatch(x->x.getName().equals("fromAssets")&&Arrays.equals(x.getParameterTypes(),new Class<?>[]{CdR31aAssets.class})));
 }
